INSERT INTO report_figures
  (id, question_id, lens_id, publisher, source_title, source_url, published,
   title, subtitle, unit, unit_symbol, decimals, axis_kind, note, page_ref,
   quote, sort_order)
VALUES
  ('imf-macro-frontier-model-query-price', 'markets', NULL,
   'International Monetary Fund', 'Global Economic and Financial Implications of Artificial Intelligence', 'https://www.imf.org/en/publications/imf-notes/issues/2026/04/03/global-economic-and-financial-implications-of-artificial-intelligence-lessons-from-a-574924', '2026-04-03',
   'Advertised price of querying a frontier AI model', 'List price per million tokens for the four models the chart labels with a price, March 2023 to September 2025', 'US dollars per million tokens',
   '$', 2, 'category',
   'Not a constant-quality price series and not IMF data. The chart is reproduced from Ethan Mollick''s ''One Useful Thing'' via a Google DeepMind presentation to the workshop. The four models sit at different points on a capability-cost trade-off measured by GPQA Diamond score: GPT-5 Nano at $0.14 is the cheap end of the cost-efficiency frontier, not a like-for-like replacement for GPT-4. Five other models are plotted with no price shown, so those are omitted here. List prices are what a provider advertises, not what buyers pay at volume or what serving actually costs.', 'p. 6', 'Shifting frontier of AI model performance and cost. Cost of querying a trained model (price per 1M tokens). GPT-4, Mar ''23 ($37.50); GPT-5 (High), Aug ''25 ($3.63); Grok 4, Sep ''25 ($0.28); GPT-5 Nano, Aug ''25 ($0.14)',
   10)
