   quote, sort_order)
VALUES
  ('imf-macro-inference-cost-decline', 'markets', NULL,
   'International Monetary Fund', 'Global Economic and Financial Implications of Artificial Intelligence', 'https://www.imf.org/en/publications/imf-notes/issues/2026/04/03/global-economic-and-financial-implications-of-artificial-intelligence-lessons-from-a-574924', '2026-04-03',
   'Fall in the cost of querying an AI model along three frontiers, March 2023 to Aug-Sep 2025', 'Percentage change in price per million tokens between the March 2023 starting model and the latest model on each of the chart''s three frontiers', '% change in price per million tokens',
   '%', 1, 'category',
   'These three figures are annotations printed on the three dashed and solid frontier lines of Figure 2, not values from a table. Each frontier ends at a different model, so the three declines are not comparable measures of the same thing: the capability frontier holds performance highest and falls least, the cost-efficiency frontier trades performance away and falls most. The running text on the same page summarises this as inference prices for certain frontier models ''dropping by over 99 percent''. Source is a chart by Ethan Mollick reproduced in the IMF note, not IMF calculation, and it covers advertised list prices only.', 'p. 6', '-93% cost; -99.4% cost; -99.7% cost',
   11)
