-- International Monetary Fund · p. 5
INSERT INTO report_figures
  (id, question_id, lens_id, publisher, source_title, source_url, published,
   title, subtitle, unit, unit_symbol, decimals, axis_kind, note, page_ref,
   quote, sort_order)
VALUES
  ('imf-macro-agi-forecast-horizon', NULL, 'growth',
   'International Monetary Fund', 'Global Economic and Financial Implications of Artificial Intelligence', 'https://www.imf.org/en/publications/imf-notes/issues/2026/04/03/global-economic-and-financial-implications-of-artificial-intelligence-lessons-from-a-574924', '2026-04-03',
   'Forecast years until artificial general intelligence arrives', 'Metaculus community forecast on when the first general AI system will be devised, tested and publicly announced; labelled points from mid-2020 to end-2024', 'years until AGI',
   'yr', 0, 'category',
   'A crowd forecast, not a measurement and not an IMF projection. These are the four points the chart annotates on a Metaculus community forecast series, plotted on a log scale and reproduced in the note from a Google DeepMind presentation; two of them (''~50 years'', ''~18 years'') are printed as approximations. Forecasters are self-selected volunteers, the horizon depends entirely on how the question defines a ''general AI system'', and a shortening forecast is evidence about what forecasters believe, not about what AI can do. The note''s own text puts the current tech-community view at 8-10 years, which does not match the chart''s latest point of 5.', 'p. 5', 'Pre-GPT average 80 years; ~50 years; ~18 years; Latest data point 5 years',
   21)
