-- International Monetary Fund · pp. 15-16
INSERT INTO report_figures
  (id, question_id, lens_id, publisher, source_title, source_url, published,
   title, subtitle, unit, unit_symbol, decimals, axis_kind, note, page_ref,
   quote, sort_order)
VALUES
  ('imf-skills-us-local-labour-market-effects', 'jobs', NULL,
   'International Monetary Fund', 'Bridging Skill Gaps for the Future: New Jobs Creation in the AI Age', 'https://www.imf.org/-/media/files/publications/sdn/2026/english/sdnea2026001.pdf', '2026-01-01',
   'Estimated wage and employment effect of demand for new skills in US local labour markets', 'US commuting zones, 2013-23; effect of a rise in the share of local job postings that require at least one new skill', '% change in wages or employment',
   '%', 1, 'category',
   'Model output, not observed change. These are coefficients from an instrumental-variable shift-share regression across US commuting zones, instrumented on early new-skill adoption in California and the United Kingdom. The second series is not a separate measurement: it applies the same estimated elasticity to the 3.3 percentage point rise in new-skill postings that was actually observed over 2013-23. The comparable German estimate is a 0.9 percent wage gain per percentage point with no statistically significant employment effect. New skills here means all new skills; AI-specific skills behave differently.', 'pp. 15-16', 'A 1 percentage point increase in job postings requiring new skills raises average hourly wages by 2.3 percent, which translates into a predicted gain of about 7.6 percent given the observed increase in new skill postings of 3.3 percentage points over the period considered. Employment effects are also positive, with the same increase in new skills linked to 1.3 percent higher employment, amounting to a predicted rise of about 4.3 percent, while the estimated effect on population is at 5.3 percent.',
   12)
ON CONFLICT (id) DO UPDATE SET
  question_id = EXCLUDED.question_id, lens_id = EXCLUDED.lens_id,
