  ('imf-skills-us-local-labour-market-effects', 'Per 1 percentage point rise in new-skill postings', 'Employment', 1, 1.3),
  ('imf-skills-us-local-labour-market-effects', 'Predicted total over 2013-23 (3.3 pp observed rise)', 'Average hourly wages', 2, 7.6),
  ('imf-skills-us-local-labour-market-effects', 'Predicted total over 2013-23 (3.3 pp observed rise)', 'Employment', 3, 4.3);

-- International Monetary Fund · p. 14
INSERT INTO report_figures
  (id, question_id, lens_id, publisher, source_title, source_url, published,
   title, subtitle, unit, unit_symbol, decimals, axis_kind, note, page_ref,
   quote, sort_order)
VALUES
  ('imf-skills-wage-premium-four-plus-new-skills', NULL, 'labour',
   'International Monetary Fund', 'Bridging Skill Gaps for the Future: New Jobs Creation in the AI Age', 'https://www.imf.org/-/media/files/publications/sdn/2026/english/sdnea2026001.pdf', '2026-01-01',
   'Posted wage premium for vacancies listing four or more new skills', 'Online job postings with advertised pay, United Kingdom and United States, 2020-24 (Lightcast)', '% higher posted hourly wage',
   '%', 1, 'category',
   'A regression coefficient on advertised pay, not on pay actually received. Postings are compared only within the same 4-digit occupation, 6-digit industry, county and year, and the number of skills listed is controlled for, so this is the marginal value of a new skill over an existing one. It is an association: employers that ask for several new skills may differ in ways the fixed effects do not capture. Only US and UK postings carry usable wage data. The premium for any single new skill is much smaller, about 3 to 3.4 percent.', 'p. 14', 'The wage premium is higher when employers demand multiple new skills—reaching 15.1 percent in the United Kingdom for vacancies listing four or more new skills and 8.5 percent in the United States.',
   31)
ON CONFLICT (id) DO UPDATE SET
  question_id = EXCLUDED.question_id, lens_id = EXCLUDED.lens_id,
  publisher = EXCLUDED.publisher, source_title = EXCLUDED.source_title,
