-- International Monetary Fund · p. 21
INSERT INTO report_figures
  (id, question_id, lens_id, publisher, source_title, source_url, published,
   title, subtitle, unit, unit_symbol, decimals, axis_kind, note, page_ref,
   quote, sort_order)
VALUES
  ('imf-skills-degree-share-by-new-skill-use', 'entry-level', NULL,
   'International Monetary Fund', 'Bridging Skill Gaps for the Future: New Jobs Creation in the AI Age', 'https://www.imf.org/-/media/files/publications/sdn/2026/english/sdnea2026001.pdf', '2026-01-01',
   'Share of workers holding at least a bachelor''s degree, by whether their profile lists new skills', 'Nearly 18 million US online worker profiles with job information updated in 2024 (Lightcast)', '% of workers with a bachelor''s degree or higher',
   '%', 1, 'category',
   'Self-reported online CVs and profiles, not a representative labour force survey. People who publish a profile skew towards professional and graduate-level work, so the absolute levels are likely too high; the gap between the groups is the more reliable part. Listing a skill is not evidence of proficiency in it.', 'p. 21', 'The evidence shows that 85 percent of workers listing new skills on their profiles have at least a bachelor''s degree, compared with 60 percent among workers who list only non-new skills (Figure 11, panel 1). A similar pattern emerges for new IT skills: 84.5 percent of workers reporting these skills hold at least a bachelor''s degree. Among new non-IT skills holders, the proportion of workers with at least a bachelor''s degree is similar, at 86 percent.',
   13)
