-- International Monetary Fund · p. 15
INSERT INTO report_figures
  (id, question_id, lens_id, publisher, source_title, source_url, published,
   title, subtitle, unit, unit_symbol, decimals, axis_kind, note, page_ref,
   quote, sort_order)
VALUES
  ('imf-skills-new-skill-rate-by-job-title', 'vacancies', NULL,
   'International Monetary Fund', 'Bridging Skill Gaps for the Future: New Jobs Creation in the AI Age', 'https://www.imf.org/-/media/files/publications/sdn/2026/english/sdnea2026001.pdf', '2026-01-01',
   'Share of US job postings listing at least one new skill, by whether the job title itself is new', 'US online job postings (Lightcast); new skills are those barely present in postings in 2010-11 that have since become common', '% of job postings listing a new skill',
   '%', 1, 'category',
   'Online postings over-represent formal, urban and higher-skill occupations, so this is the formal professional labour market rather than all US hiring. A posting is a request, not a hire. The paper is explicit that postings with emerging titles do not carry higher pay, so a new title is not by itself a sign of a better job.', 'p. 15', 'In the United States, job postings with new, emerging job titles are twice as likely to list a new skill as opposed to postings with existing titles (16.8 percent versus 8.8 percent). Yet job postings with emerging titles are not associated with higher wages.',
   12)
