-- International Monetary Fund · p. 20
INSERT INTO report_figures
  (id, question_id, lens_id, publisher, source_title, source_url, published,
   title, subtitle, unit, unit_symbol, decimals, axis_kind, note, page_ref,
   quote, sort_order)
VALUES
  ('imf-skills-ai-exposed-employment-shortfall', 'jobs', NULL,
   'International Monetary Fund', 'Bridging Skill Gaps for the Future: New Jobs Creation in the AI Age', 'https://www.imf.org/-/media/files/publications/sdn/2026/english/sdnea2026001.pdf', '2026-01-01',
   'Estimated employment shortfall in AI-exposed occupations five years after AI skills appear locally', 'US commuting zones; occupations highly exposed to AI with limited scope for complementarity, measured five years after AI-related skills first appear in local job postings', '% difference in employment level versus other regions',
   '%', 1, 'category',
   'Model output, not a headcount of jobs lost. Both figures come from a staggered difference-in-differences event study on US commuting zones; the second is the same estimated coefficient scaled to the 0.57 percentage point rise in AI-skill postings actually observed. Effects were statistically insignificant for occupations that are highly exposed but highly complementary to AI, and the paper cites French firm-level evidence pointing the other way. Around 30 percent of US employment falls in the high-exposure, low-complementarity group.', 'p. 20', 'In the medium term (after five years), regions with a 1 percentage point higher demand for AI-related skills show employment levels that are 6.3 percent lower than other regions for occupations that are highly exposed to AI with limited scope for complementarity. This translates into a predicted lower employment level of about 3.6 percent given the observed increase in new skill postings (which amounts to 0.57 percentage point for workers in high-exposure, low-complementarity occupations over the period considered).',
   13)
