   quote, sort_order)
VALUES
  ('kpmg-outcomes-by-ceo-accountability', 'productivity', NULL,
   'KPMG International', 'Global AI Pulse, Q2 2026', 'https://kpmg.com/xx/en/our-insights/ai-and-technology/ai-pulse.html', '2026-06-01',
   'Reported AI outcomes where the CEO is accountable against where they are not', 'Share strongly agreeing with each statement, split by whether the CEO is accountable for AI outcomes; senior leaders across 20 countries and territories, Q2 2026 (n=2,145)', '% strongly agreeing',
   '%', 0, 'category',
   'A quarterly executive survey of 2,145 senior leaders, fielded online 28 April to 25 May 2026. This is a cross-sectional association, not evidence that clear accountability causes better outcomes — organizations further along with AI are plausibly both more likely to have assigned accountability and more likely to report returns. Both the split and the outcomes are self-reported by the same respondent, which inflates consistency. KPMG does not publish the sub-group sizes behind each split.', 'p. 16', 'The strongest outcomes are reported where accountability is clearly defined ... To what extent do you agree or disagree with the following statements? Percentage that strongly agree. Q2 (n=2145)',
   15)
