INSERT INTO report_figures
  (id, question_id, lens_id, publisher, source_title, source_url, published,
   title, subtitle, unit, unit_symbol, decimals, axis_kind, note, page_ref,
   quote, sort_order)
VALUES
  ('mckinsey-gen-ai-revenue-increase-by-function', 'productivity', NULL,
   'McKinsey & Company (QuantumBlack)', 'The State of AI: How Organizations Are Rewiring to Capture Value', 'https://www.mckinsey.com/capabilities/quantumblack/our-insights/the-state-of-ai-how-organizations-are-rewiring-to-capture-value', '2025-03-01',
   'Share of respondents reporting a revenue increase in the business unit using gen AI, by function', 'Respondents whose organizations regularly use gen AI in the given function; first-half 2024 survey (fielded 22 Feb - 5 Mar 2024) compared with second-half 2024 survey (16-31 July 2024)', '% of respondents',
   '%', 0, 'category',
   'Survey perception, not measured revenue: respondents are estimating the revenue effect of gen AI on their own unit, with no accounting basis and no control for what would have happened anyway. Values are the totals printed at the end of each stacked bar, summing three bands (increase by more than 10%, 6-10%, and 5% or less); segments may not sum exactly to the printed total because of rounding. Asked only of those reporting regular gen AI use in that function, so the base differs by function and by wave; respondents saying ''no change'', ''decreased revenue'', ''don''t know'' or ''not applicable'', and functions that are cost centres, are excluded. McKinsey notes elsewhere in the same report that more than 80% of respondents say their organizations see no tangible effect on enterprise-level EBIT.', 'p. 22', 'Organizations increasingly see gen AI''s effects on revenues in the business units using the technology. Revenue increase within business units from gen AI use, past 12 months, by function, % of respondents',
   12)
