-- OECD · p. 44
INSERT INTO report_figures
  (id, question_id, lens_id, publisher, source_title, source_url, published,
   title, subtitle, unit, unit_symbol, decimals, axis_kind, note, page_ref,
   quote, sort_order)
VALUES
  ('oecd-software-share-of-us-private-capital', 'money', NULL,
   'OECD', 'OECD Economic Outlook, Volume 2026 Issue 1', 'https://www.oecd.org/en/publications/2026/06/oecd-economic-outlook-volume-2026-issue-1_8be0dba6.html', '2026-06-01',
   'Software sector share of US private capital portfolios', 'US business development companies'' portfolios and new investments by US private equity funds, end-2025', '% of portfolio / of new investments',
   '%', 0, 'category',
   'The two shares are not measured the same way: 20% is a share of an existing stock of portfolio exposures, 42% is a share of the flow of new investments made during 2025, so the second will move faster than the first. ''Software'' is a sector label, not an AI label — it covers software and technology services firms generally, and the OECD uses it as a proxy for AI-linked exposure rather than a direct measure of it. Valuations of private, illiquid holdings are set by fund managers with, in the OECD''s words, significant discretion.', 'p. 44', 'Private equity and credit funds are particularly exposed to the performance of technology-related companies, with the software sector accounting for 20% of US business development companies'' portfolios and 42% of new investments of US private equity funds in 2025 (Figure 1.27, Panel B).',
