INSERT INTO report_figures
  (id, question_id, lens_id, publisher, source_title, source_url, published,
   title, subtitle, unit, unit_symbol, decimals, axis_kind, note, page_ref,
   quote, sort_order)
VALUES
  ('pwc-productivity-growth-by-ai-exposure', 'productivity', NULL,
   'PwC', '2026 Global AI Jobs Barometer', 'https://www.pwc.com/gx/en/issues/artificial-intelligence/job-barometer/2026/2026-global-ai-jobs-barometer-full-report.pdf', NULL,
   'Firm productivity growth since 2018, most vs least AI-exposed companies', 'Average firm growth in revenue per employee against a 2018 baseline, 2022-2025, companies with turnover of at least $50m USD, global', '% growth in revenue per employee vs 2018',
   '%', 1, 'year',
   'Company AI exposure is inferred from the NAICS sector a firm is tagged to in ORBIS, not from any measure of what the firm actually does with AI — so this is a sector-level proxy. Productivity is turnover per employee, a topline measure that rises if revenue grows for any reason. 2025 uses 2024 data where 2025 is missing. Firms that exited the market are excluded, creating survivorship bias, and the sample skews to larger, better-reporting firms. The comparison between the two quartiles is more meaningful than either absolute rate.', 'p. 19', 'Since 2022 when AI adoption soared, the most AI-exposed companies have seen faster productivity growth. Average firm growth rate in productivity by AI exposure quartile (measured using a 2018 baseline)',
   10)
