-- PwC · p. 13
INSERT INTO report_figures
  (id, question_id, lens_id, publisher, source_title, source_url, published,
   title, subtitle, unit, unit_symbol, decimals, axis_kind, note, page_ref,
   quote, sort_order)
VALUES
  ('pwc-entry-level-postings-seniorised', 'entry-level', NULL,
   'PwC', '2026 Global AI Jobs Barometer', 'https://www.pwc.com/gx/en/issues/artificial-intelligence/job-barometer/2026/2026-global-ai-jobs-barometer-full-report.pdf', NULL,
   'Change in entry-level job postings, seniorised vs non-seniorised roles', 'Entry-level postings (0-2 years experience) in the top AI exposure quartile, United States, change between 2019 and 2025', '% change in entry-level job postings, 2019 to 2025',
   '%', 0, 'category',
   'US only, and only within the most AI-exposed quartile of jobs. ''Seniorised'' is a threshold PwC defines: a posting counts if it contains at least ten mentions of a skill that is both new for that occupation and traditionally seen only in experienced roles. Entry level is proxied by the years-of-experience field in Lightcast postings. This counts vacancies advertised, not jobs filled, and shows association, not that AI caused the divergence.', 'p. 13', 'Change in entry-level job postings between 2019 and 2025, seniorised vs non-seniorised roles, top AI exposure quartile, US',
