INSERT INTO report_figures
  (id, question_id, lens_id, publisher, source_title, source_url, published,
   title, subtitle, unit, unit_symbol, decimals, axis_kind, note, page_ref,
   quote, sort_order)
VALUES
  ('wef-business-ai-adoption-2022-2025', 'adoption', NULL,
   'World Economic Forum', 'Four Futures for Jobs in the New Economy: AI and Talent in 2030', 'https://www.weforum.org/publications/four-futures-for-jobs-in-the-new-economy-ai-and-talent-in-2030/', '2026-01-01',
   'Share of businesses using AI in at least one function', 'Global firms, 2022 compared with the latest available estimate cited in the paper (McKinsey, 2025)', '% of businesses',
   '%', 0, 'year',
   'Self-reported survey data from McKinsey''s state-of-AI survey, not administrative or transaction data. ''Using AI in at least one function'' is a very low bar — a firm clears it with one team trialling a chatbot, so this measures reach, not depth or scale of use. The respondent panel is not a random sample of the world''s firms and skews towards larger organisations, and the two years are not necessarily the same set of respondents.', 'p. 5', 'Over the last few years, AI has moved from experimentation to workflow integration, with the share of businesses using AI in at least one function increasing from 55% in 2022 to 88% in the latest estimates.',
   20)
