INSERT INTO report_figures
  (id, question_id, lens_id, publisher, source_title, source_url, published,
   title, subtitle, unit, unit_symbol, decimals, axis_kind, note, page_ref,
   quote, sort_order)
VALUES
  ('wef-task-automation-age-of-displacement-2030', NULL, 'labour',
   'World Economic Forum', 'Four Futures for Jobs in the New Economy: AI and Talent in 2030', 'https://www.weforum.org/publications/four-futures-for-jobs-in-the-new-economy-ai-and-talent-in-2030/', '2026-01-01',
   'Share of tasks absorbed by technology by 2030 under the Age of Displacement scenario', 'Scenario 2 of four, exponential AI advancement with limited workforce readiness, global position in 2030', '% of tasks performed by technology',
   '%', 0, 'category',
   'This is a scenario, not a forecast or a measurement. The Forum states the four futures are stylized narratives built from workshops with chief strategy officers, with directionality ''illustrative and for scenario-building purposes only''. The two values are also thresholds in the original wording — the paper says tasks have ''surpassed 50%'' and are ''approaching 90%'' in high-exposure sectors, so treat them as boundaries the scenario crosses rather than point estimates. Nothing here describes the world as it is.', 'p. 10', 'The share of tasks absorbed by technology has surpassed 50%, approaching 90% in high-exposure sectors.',
   21)
